/* =================================================================================================
FILE:         01_sdi_sp_dashboardPulseTms_bronze_adobeFunnel_weekly.sql   (Databricks port)
LAYER:        Stored Procedure
PROCEDURE:    sdi_sp_dashboardPulseTms_bronze_adobeFunnel_weekly

PURPOSE:
  Creates/refreshes physical table sdi_tbl_dashboardPulseTms_bronze_adobeFunnel_weekly.
  Called as part of the weekly refresh.

CHANNEL GROUPS (standard vocabulary):
  'All Channels' | 'Paid Search' | 'Paid Social' | 'Organic Search' |
  'Direct' | 'Programmatic' | 'Other'

PORTING NOTES (BQ -> Databricks), applies to this file only:
  - Adobe/Improvado raw source tables now live under prd_dbi_analytics.improvado.<table>
    (was prj-dbi-prd-1.ds_dbi_improvado_master.<table> in BigQuery) -- per your confirmation.
  - PARSE_DATE('%Y%m%d', date_yyyymmdd) -> to_date(date_yyyymmdd, 'yyyyMMdd')
  - DATE_ADD(x, INTERVAL 6 DAY)         -> date_add(x, 6)
  - SAFE_CAST(x AS FLOAT64)             -> TRY_CAST(x AS DOUBLE)
  - QUALIFY ROW_NUMBER() ... = 1        -> unchanged; Databricks SQL supports QUALIFY natively (DBR 10.4 LTS+)
  - STRING_AGG(DISTINCT x, ', ' ORDER BY x) -> array_join(sort_array(collect_set(x)), ', ')
    ⚠ REVISED after hitting a real Databricks bug: this originally used
    string_agg(DISTINCT x, ', ') WITHIN GROUP (ORDER BY x), which is the more direct syntactic
    equivalent of BQ's STRING_AGG. That works fine with ONE such call in a query, but this
    procedure has TWO (source_tables_used and filenames_used, over different columns) in the
    same GROUP BY. With two different-column DISTINCT string_agg calls in one aggregate,
    Spark's RewriteDistinctAggregates optimizer rule throws a ClassCastException inside
    ListAgg.withNewChildrenInternal (AttributeReference cannot be cast to SortOrder) --
    confirmed against DBR's actual execution, not just a syntax guess. collect_set() +
    sort_array() + array_join() produces the identical result (deduplicated, sorted,
    comma-joined) using older, more mature Spark functions that don't go through that rewrite
    path, so it sidesteps the bug entirely rather than working around it.
  - MAX(IF(cond, val, NULL))            -> unchanged; Databricks SQL supports IF() as a CASE WHEN alias
  - OPTIONS(strict_mode=false)          -> dropped; BQ-scripting-only setting, no Databricks equivalent
  - CREATE TABLE ... PARTITION BY x CLUSTER BY y ... OPTIONS(description=...)
                                         -> CREATE TABLE ... CLUSTER BY (x, y) COMMENT '...'
                                            (Databricks Liquid Clustering supersedes the BQ partition+cluster split)
  - CREATE OR REPLACE PROCEDURE ... BEGIN...END -> needs explicit LANGUAGE SQL clause

ADOBE METRICS ADDED AFTER THE ORIGINAL 14 (read directly from the raw Adobe tables, like every other metric here):
  c2cVisitors            visitors     sdi_raw_adobe_pp_upv_{group}_c2c_weekly_tmo     click to call, UPVs with a call
  chatEngagementVisitors visitors     sdi_raw_adobe_pp_upv_{group}_chat_weekly_tmo    chat engagement (catch-all VR + Care)
  ecCompletedPageEvents  page_events  sdi_raw_adobe_pp_ec_{group}_ec_completed_weekly_tmo          broadband Eligibility Check completed (EVENT count)
  ecSuccessfulVisits     visits       sdi_raw_adobe_pp_ec_{group}_ec_successful_visits_weekly_tmo   broadband Eligibility Check successful (VISIT count)
  where {group} = all, direct, organic_search, other, paid_search, social, programmatic.
  The two EC metrics are different units: do not divide one by the other.

METRO / TFB ADOBE mPULSE METRICS (added 2026-11-10; 18 metrics x 7 channel groups = 126 raw tables):
  Metro (lob Metro)  sdi_raw_adobe_metro_mpulse_{stem}_{allup|paidsearch|organicsearch|direct|social|programmatic|otherltc}_weekly_tmo[_tmo]
    metroProspectVisitors, metroHomepageEntryVisitors, metroDealsEntryVisitors, metroProductPlansEntryVisitors,
    metroOtherEntryVisitors, metroActivationIntentVisitors, metroCartStartVisitors,
    metroProspectClicktocallVisitors                                              (visitors)
    metroOrderConfirmationOrders                                                  (orders)
  TFB (lob TFB)      sdi_raw_adobe_tfb_mpulse_{stem}_{...same channel tokens...}_weekly_tmo[_tmo]
    tfbExclSinglePageVisitors, tfbCartStartsVisitors, tfbClicktocallExistsVisitors,
    tfbChatEngagementVisitors                                                     (visitors)
    tfbLeadgenFormCompleteEvent104, tfbCreditCheckEvent104                        (event104)
    tfbAllClicktocallEvent95                                                      (event95)
    tfbAllChatEngagementEvent21                                                   (event21)
    tfbEcommOrderHitOrders                                                        (orders)
  Units differ by metric (visitors / orders / events): never divide one by another. Unique-visitor
  metrics are not additive across channels. Metro/TFB EC is NOT repeated here: EC already exists above.
  The _tmo_tmo suffix on some raw tables is the real source table name, not a typo.

CHANGE LOG:
  - 'Social' renamed to 'Paid Social' throughout to align with standard channel_group vocabulary.
  - Added c2cVisitors, chatEngagementVisitors, ecCompletedPageEvents, ecSuccessfulVisits
    (4 metrics x 7 channel groups = 28 UNION ALL lines, and 4 pivot columns).
  - 2026-11-10: Added 18 Metro/TFB mPulse metrics (18 x 7 = 126 UNION ALL lines, and 18 pivot columns).
================================================================================================= */

CREATE OR REPLACE PROCEDURE
  prdrzranalytics.lab42.sdi_sp_dashboardPulseTms_bronze_adobeFunnel_weekly()
LANGUAGE SQL
SQL SECURITY INVOKER
AS
BEGIN

  CREATE OR REPLACE TABLE
    prdrzranalytics.lab42.sdi_tbl_dashboardPulseTms_bronze_adobeFunnel_weekly
  USING DELTA
  CLUSTER BY (week_sun_sat, channel_group)
  COMMENT 'PulseTMS Bronze — Adobe UPV funnel metrics plus C2C, chat engagement and broadband Eligibility Check (EC), plus Metro/TFB mPulse metrics (18). Wide format, one row per week_sun_sat x channel_group. Clustered by week_sun_sat, channel_group. Refreshed weekly via sdi_sp_dashboardPulseTms_bronze_adobeFunnel_weekly. Channel groups: All Channels, Paid Search, Paid Social, Organic Search, Direct, Programmatic, Other.'
  AS
  WITH RawUnion AS (

    /* ======= ALL CHANNELS ======= */
    SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6) AS week_sun_sat, 'All Channels' AS channel_group, 'upvPostpaid' AS metric_name, TRY_CAST(visitors AS DOUBLE) AS metric_value, 'sdi_raw_adobe_pp_uvnb_all_uvnb_postpaid_flow_visitors_weekly_tmo' AS source_table, __insert_date AS insert_date, File_Load_datetime AS file_load_datetime, Filename AS filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_uvnb_postpaid_flow_visitors_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'upvHsi', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_all_uvnb_hsi_flow_visitors_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_uvnb_hsi_flow_visitors_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'upvByod', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_all_uvnb_byod_flow_visitors_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_uvnb_byod_flow_visitors_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'upvFlowTotal', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_all_flow_total_visitors_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_flow_total_visitors_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'upvTotalAdobe', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_pp_pro_uvnb_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_pp_pro_uvnb_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'cartstartPostpaid', TRY_CAST(visits AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_all_postpaid_cartstart_visits_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_postpaid_cartstart_visits_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'cartstartHsi', TRY_CAST(visits AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_all_hsi_cartstart_visits_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_hsi_cartstart_visits_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'cartstartByod', TRY_CAST(visits AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_all_byod_cartstart_visits_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_byod_cartstart_visits_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'ordersUnassistedPostpaid', TRY_CAST(orders AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_all_postpaid_order_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_postpaid_order_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'ordersUnassistedHsi', TRY_CAST(orders AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_all_hsi_order_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_hsi_order_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'ordersUnassistedByod', TRY_CAST(orders AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_all_byod_order_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_byod_order_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'ordersAssistedPostpaid', TRY_CAST(orders AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_all_postpaid_order_assisted_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_postpaid_order_assisted_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'ordersAssistedHsi', TRY_CAST(orders AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_all_hsi_order_assisted_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_hsi_order_assisted_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'ordersAssistedByod', TRY_CAST(orders AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_all_byod_order_assisted_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_all_byod_order_assisted_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'c2cVisitors', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_pp_upv_all_c2c_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_upv_all_c2c_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'chatEngagementVisitors', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_pp_upv_all_chat_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_upv_all_chat_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'ecCompletedPageEvents', TRY_CAST(page_events AS DOUBLE), 'sdi_raw_adobe_pp_ec_all_ec_completed_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_ec_all_ec_completed_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'ecSuccessfulVisits', TRY_CAST(visits AS DOUBLE), 'sdi_raw_adobe_pp_ec_all_ec_successful_visits_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_ec_all_ec_successful_visits_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'metroProspectVisitors', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_metro_mpulse_pa_prospect_visitors_allup_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_metro_mpulse_pa_prospect_visitors_allup_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'metroHomepageEntryVisitors', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_metro_mpulse_pa_homepage_entry_visitors_allup_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_metro_mpulse_pa_homepage_entry_visitors_allup_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'metroDealsEntryVisitors', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_metro_mpulse_pa_deals_entry_visitors_allup_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_metro_mpulse_pa_deals_entry_visitors_allup_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'metroProductPlansEntryVisitors', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_metro_mpulse_pa_product_plans_entry_visitors_allup_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_metro_mpulse_pa_product_plans_entry_visitors_allup_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'metroOtherEntryVisitors', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_metro_mpulse_pa_other_entry_visitors_allup_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_metro_mpulse_pa_other_entry_visitors_allup_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'metroActivationIntentVisitors', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_metro_mpulse_pa_activation_intent_visitors_allup_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_metro_mpulse_pa_activation_intent_visitors_allup_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'metroCartStartVisitors', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_metro_mpulse_pa_cart_start_visitors_allup_weekly_tmo_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_metro_mpulse_pa_cart_start_visitors_allup_weekly_tmo_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'metroProspectClicktocallVisitors', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_metro_mpulse_pa_prospect_clicktocall_visitors_allup_weekly_tmo_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_metro_mpulse_pa_prospect_clicktocall_visitors_allup_weekly_tmo_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'metroOrderConfirmationOrders', TRY_CAST(orders AS DOUBLE), 'sdi_raw_adobe_metro_mpulse_pa_order_confirmation_orders_allup_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_metro_mpulse_pa_order_confirmation_orders_allup_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'tfbExclSinglePageVisitors', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_tfb_mpulse_pb_excl_single_page_visitors_allup_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_tfb_mpulse_pb_excl_single_page_visitors_allup_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'tfbLeadgenFormCompleteEvent104', TRY_CAST(event104 AS DOUBLE), 'sdi_raw_adobe_tfb_mpulse_pb_leadgen_form_complete_ev104_allup_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_tfb_mpulse_pb_leadgen_form_complete_ev104_allup_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'tfbCreditCheckEvent104', TRY_CAST(event104 AS DOUBLE), 'sdi_raw_adobe_tfb_mpulse_pb_credit_check_ev104_allup_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_tfb_mpulse_pb_credit_check_ev104_allup_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'tfbAllClicktocallEvent95', TRY_CAST(event95 AS DOUBLE), 'sdi_raw_adobe_tfb_mpulse_pb_alltfb_clicktocall_allup_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_tfb_mpulse_pb_alltfb_clicktocall_allup_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'tfbAllChatEngagementEvent21', TRY_CAST(event21 AS DOUBLE), 'sdi_raw_adobe_tfb_mpulse_pb_alltfb_chatengagement_allup_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_tfb_mpulse_pb_alltfb_chatengagement_allup_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'tfbCartStartsVisitors', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_tfb_mpulse_pb_cart_starts_visitors_allup_weekly_tmo_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_tfb_mpulse_pb_cart_starts_visitors_allup_weekly_tmo_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'tfbEcommOrderHitOrders', TRY_CAST(orders AS DOUBLE), 'sdi_raw_adobe_tfb_mpulse_pb_ecomm_order_hit_orders_allup_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_tfb_mpulse_pb_ecomm_order_hit_orders_allup_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'tfbClicktocallExistsVisitors', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_tfb_mpulse_pb_clicktocall_exists_visitors_allup_weekly_tmo_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_tfb_mpulse_pb_clicktocall_exists_visitors_allup_weekly_tmo_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'All Channels', 'tfbChatEngagementVisitors', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_tfb_mpulse_pb_alltfb_chatengagement_allup_weekly_tmo_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_tfb_mpulse_pb_alltfb_chatengagement_allup_weekly_tmo_tmo

    /* ======= DIRECT ======= */
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'Direct', 'upvPostpaid', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_direct_uvnb_postpaid_flow_visitors_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_direct_uvnb_postpaid_flow_visitors_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'Direct', 'upvHsi', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_direct_uvnb_hsi_flow_visitors_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_direct_uvnb_hsi_flow_visitors_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'Direct', 'upvByod', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_direct_uvnb_byod_flow_visitors_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_direct_uvnb_byod_flow_visitors_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'Direct', 'upvFlowTotal', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_direct_flow_total_visitors_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_direct_flow_total_visitors_weekly_tmo
    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'Direct', 'upvTotalAdobe', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_pp_uvnb_direct_uvnb_visitors_weekly_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_pp_uvnb_direct_uvnb_visitors_weekly_tmo
