    UNION ALL SELECT date_add(to_date(date_yyyymmdd, 'yyyyMMdd'), 6), 'Programmatic', 'tfbClicktocallExistsVisitors', TRY_CAST(visitors AS DOUBLE), 'sdi_raw_adobe_tfb_mpulse_pb_clicktocall_exists_visitors_programmatic_weekly_tmo_tmo', __insert_date, File_Load_datetime, Filename FROM prd_dbi_analytics.improvado.sdi_raw_adobe_tfb_mpulse_pb_clicktocall_exists_visitors_programmatic_weekly_tmo_tmo
